// real Salesforce calls are skipped (routers test is_mock_run == true) and the AI Actions
// run against the edited test email. Nothing here runs on the live path.

// --- inputs -----------------------------------------------------------------
let test_subject = ZT.getVariableValue("test_subject", "Testing Case");
